<div class="page-heading"><div><p class="eyebrow">Connections</p><h1>Chatbot integrations</h1><p class="muted">Server credentials are separate from general API keys and limited to explicitly selected chatbots.</p></div><a class="button button-primary" href="/admin/integration-credentials/create">Create credential</a></div>
<?php if(is_string($message)&&$message!==''):?><div class="alert alert-success" role="status"><?= $escape($message) ?></div><?php endif;?>
<?php if($page->items===[]):?><section class="empty-state"><h2>No integration credentials</h2><p>Create one for a trusted server application. Browser widgets do not need this credential.</p></section><?php else:?><div class="table-card"><table><thead><tr><th>Name</th><th>Prefix</th><th>Scoped chatbots</th><th>Status</th><th>Requests</th><th>Provider tokens</th><th>Last used</th><th>Actions</th></tr></thead><tbody><?php foreach($page->items as $credential):?><?php $expired=$credential->expiresAt!==null&&strtotime($credential->expiresAt)<=time();$status=$expired?'expired':$credential->status;?><tr class="<?= $status==='active'?'':'row-muted' ?>"><td><strong><?= $escape($credential->name) ?></strong></td><td><code><?= $escape($credential->visiblePrefix) ?>…</code></td><td><?php foreach($credential->chatbotIds as $id):?><span class="badge"><?= $escape($chatbots[$id]??'#'.$id) ?></span> <?php endforeach;?></td><td><?= $escape(ucfirst($status)) ?></td><td><?= $escape(number_format($credential->requestCount)) ?></td><td><?= $escape(number_format($credential->providerTokens)) ?></td><td><?= $escape($formatDate($credential->lastUsedAt)) ?></td><td><div class="action-row"><?php if($status==='active'):?><form method="post" action="/admin/integration-credentials/<?= $credential->id ?>/revoke" data-confirm="Revoke this integration credential?"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><button class="button button-quiet">Revoke</button></form><?php endif;?><form method="post" action="/admin/integration-credentials/<?= $credential->id ?>/delete" data-confirm="Permanently delete this credential record?"><input type="hidden" name="_csrf" value="<?= $escape($csrfToken) ?>"><button class="button button-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php require dirname(__DIR__).'/partials/list_pagination.php';?><?php endif;?>
